use vstd::prelude::*;

verus! {

spec fn rev_index(n: nat, j: nat) -> nat {
    // for j in 0..n, this is the source index when building the reversed array
    (n - 1 - j)
}

fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
    ensures
        a_rev.len() == a.len(),
        forall|j: int| 0 <= j < a.len() ==> a_rev[j] == a[(a.len() - 1 - j) as int],
{
    let n = a.len();
    let mut a_rev = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == a.len(),
            a_rev.len() <= n,
            // a_rev is exactly the reverse of the suffix already processed:
            // processed indices are i+1 .. n-1, so a_rev length is n-1-i
            a_rev.len() == n - 1 - i,
            forall|j: int|
                0 <= j < a_rev.len() ==>
                    a_rev[j] == a[(n - 1 - j) as int],
    {
        a_rev.push(a[i]);
        assert(a_rev[a_rev.len() as int - 1] == a[i as int]);
    }

    a_rev
}

} // verus!

